function stageThemeIndexForPosition(x,y){
 if(gameMode==='expedition'&&expeditionRooms.length){
  const room=whichExpeditionRoom(x,y,0);if(room)return Math.max(0,Math.min(TOTAL_ROOMS-1,room.i));
  for(const hall of expeditionCorridors){if(x>=hall.left&&x<=hall.right&&y>=hall.top&&y<=hall.bottom)return Math.max(0,Math.min(TOTAL_ROOMS-1,hall.i+1));}
  return Math.max(0,Math.min(TOTAL_ROOMS-1,regionIndex));
 }
 return 0;
}
function getStageTheme(stageKey,idx=0){
 const base=stageDefs[stageKey]||stageDefs.ruins;
 const roomThemes=stageRoomThemes[stageKey]||[];
 const override=roomThemes[Math.max(0,Math.min(roomThemes.length-1,idx))]||{};
 return Object.assign({},base,override,{seed:(base.seed||0)+idx*997});
}
function activeStageTheme(){return getStageTheme(selectedStage,gameMode==='expedition'?Math.max(0,Math.min(TOTAL_ROOMS-1,regionIndex)):0)}

