const SAVE_KEY='maremon-survivors-v29-progress';
const BUILD_VERSION='v407';
function newProgress(){return{kills:0,runs:0,wins:0,normalWins:0,hardWins:0,nightmareWins:0,survivalWins:0,bestLevel:1,maxFollowers:0,boostSuccess:0,eliteKills:0,relics:0,evolutions:0,enemyKills:{},stageEnemyKills:{},patronBoosts:{},achievements:[],clears:{},difficultySelections:{}}}
function loadProgress(){try{const p=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');return p&&typeof p==='object'?Object.assign(newProgress(),p):newProgress()}catch(e){return newProgress()}}
let progress=loadProgress(),difficulty='normal';for(const field of ['enemyKills','stageEnemyKills','patronBoosts','difficultySelections','clears'])if(!progress[field]||typeof progress[field]!=='object'||Array.isArray(progress[field]))progress[field]={};
let saveFileHandle=null,saveWriteBusy=false,saveWriteScheduled=false,saveLastWrite=0;
let saveReady=false,saveDirty=false,saveTimer=null;
const saveOptions={mode:'readwrite'};
const FILE_NAME='Maremon_Save.json';
function saveProgress(){
 let ok=true;
 try{localStorage.setItem(SAVE_KEY,JSON.stringify(progress))}catch(e){ok=false;console.warn('ブラウザ内保存失敗',e)}
 if(saveFileHandle&&saveReady){saveDirty=true;scheduleSaveToFile()}
 return ok;
}
function buildPortableSave(){return {app:'maremon-survivors',formatVersion:1,exportedAt:new Date().toISOString(),progress:cleanProgress(progress),difficultyPreference:difficulty}}
function saveDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('maremon-save-handle',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('files'))req.result.createObjectStore('files')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function readStoredSaveHandle(){const db=await saveDb();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly');const r=tx.objectStore('files').get('active');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}finally{db.close()}}
async function storeSaveHandle(handle){const db=await saveDb();try{await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(handle,'active');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}finally{db.close()}}
function readableFileInfo(handle){return handle&&handle.name?handle.name:FILE_NAME}
function updateSaveLocation(){const el=$('saveLocationLabel');if(el)el.textContent=saveFileHandle&&saveReady?'保存先：'+readableFileInfo(saveFileHandle)+'（自動読み込み・自動上書き有効）':saveFileHandle?'保存先：'+readableFileInfo(saveFileHandle)+'（アクセス許可待ち・ファイルの自動上書き停止中）':'保存先：未設定（ブラウザ内に自動保存中）'}
function scheduleSaveToFile(){
 if(!saveFileHandle||!saveReady||saveTimer)return;
 const delay=Math.max(700,3500-(Date.now()-saveLastWrite));
 saveTimer=setTimeout(async()=>{saveTimer=null;await flushSaveFile(false);if(saveDirty&&saveReady&&saveFileHandle&&(!saveTimer)){
   // If browser permissions disappeared, do not spin forever. A new user click is required.
   try{if(await saveFileHandle.queryPermission(saveOptions)==='granted')scheduleSaveToFile()}catch(e){}
 }},delay)
}
async function flushSaveFile(force=false){
 if(!saveFileHandle||!saveReady)return false;
 if(saveWriteBusy){saveDirty=true;return false}
 saveWriteBusy=true;
 try{
  let allowed=await saveFileHandle.queryPermission(saveOptions);
  if(allowed!=='granted'&&force)allowed=await saveFileHandle.requestPermission(saveOptions);
  if(allowed!=='granted'){
   saveReady=false;updateSaveLocation();saveNotice('ファイルへのアクセス許可が切れています。保存先設定から再許可してください。',true);
   return false;
  }
  const text=JSON.stringify(buildPortableSave(),null,2)+'\n';
  // A snapshot is written; changes during write will be committed in the next pass.
  saveDirty=false;
  const stream=await saveFileHandle.createWritable();await stream.write(text);await stream.close();saveLastWrite=Date.now();
  if(force)saveNotice('「'+readableFileInfo(saveFileHandle)+'」へ保存しました。以降も自動更新します。');
  return true;
 }catch(e){saveDirty=true;saveReady=false;updateSaveLocation();saveNotice('外部セーブの書き込み失敗：'+e.message+'。JSONのバックアップを取ってください。',true);return false}
 finally{saveWriteBusy=false}
}
function validateSaveDocument(data){
 if(!data||data.app!=='maremon-survivors'||data.formatVersion!==1)throw new Error('別のゲームまたは未対応形式のセーブです。');
 return cleanProgress(data.progress)
}
async function loadFromHandle(handle){
 const file=await handle.getFile();
 if(!file.size)return false;
 if(file.size>262144)throw new Error('セーブファイルが256KBを超えています。');
 const data=JSON.parse(await file.text());
 const incoming=validateSaveDocument(data);
 progress=incoming;
 restoreDifficultyFromSave(data);
 if(!isGodUnlocked(patron))patron='cthulhu';
 // Save was read before enabling writes; never overwrite it with stale browser progress.
 try{localStorage.setItem(SAVE_KEY,JSON.stringify(progress))}catch(e){console.warn('ブラウザへの同期失敗',e)}
 checkAchievements();
 renderAchievements();
 updateSaveLocation();
 return true;
}
async function activateSaveHandle(handle){
 // Called only from a user's click or an already-granted restored handle.
 let allowed=await handle.queryPermission(saveOptions);
 if(allowed!=='granted')allowed=await handle.requestPermission(saveOptions);
 if(allowed!=='granted')throw new Error('ファイルの読み書き権限が許可されていません。');
 const previousReady=saveReady;saveReady=false;
 if(saveTimer){clearTimeout(saveTimer);saveTimer=null;}
 let loaded;try{loaded=await loadFromHandle(handle)}catch(err){saveReady=previousReady;throw err} // Never overwrite an unreadable file
 saveFileHandle=handle;saveReady=true;
 try{await storeSaveHandle(handle)}catch(e){saveNotice('ゲーム中は保存できますが、保存先の記憶に失敗しました。次回は再指定してください。',true)}
 updateSaveLocation();
 if(!loaded){saveDirty=true;await flushSaveFile(true)}
 else saveNotice('「'+readableFileInfo(handle)+'」から自動読み込みしました。変更時は同じファイルへ自動上書きします。');
 if(saveDirty)scheduleSaveToFile();
 return loaded;
}
async function chooseSaveFile(){
 if(typeof window.showSaveFilePicker!=='function')throw new Error('このブラウザは保存先の自動上書きに対応していません。JSONの手動保存を利用してください。');
 // Transient user activation: call picker directly from the button handler.
 const handle=await window.showSaveFilePicker({id:'maremon-save-v35',suggestedName:FILE_NAME,types:[{description:'マレモンのセーブ',accept:{'application/json':['.json']}}]});
 return await activateSaveHandle(handle);
}
async function restoreSaveHandle(){
 if(typeof window.showSaveFilePicker!=='function')return 'unsupported';
 try{
  const handle=await readStoredSaveHandle();if(!handle)return 'unset';
  saveFileHandle=handle;
  const perm=await handle.queryPermission(saveOptions);
  if(perm!=='granted'){updateSaveLocation();return 'permission'};
  await loadFromHandle(handle);saveReady=true;updateSaveLocation();
  saveNotice('前回の「'+readableFileInfo(handle)+'」から自動読み込みしました。');
  return 'loaded';
 }catch(e){saveReady=false;saveNotice('保存先の復元に失敗：'+e.message+'。誤って上書きしないよう停止しています。',true);return 'error'}
}

