const startingGods=new Set(['cthulhu','shub','hastur','yog','nyarl']);
const startingSkills=new Set(['damage','projectile','chain','conversion','recruit','speed','health','swarm','blast','support']);
function finalGodReady(p=progress){
 return p.nightmareWins>=1&&Object.keys(pantheon).filter(id=>id!=='azathoth').every(id=>
  startingGods.has(id)||achievements.some(a=>a.god===id&&p.achievements.includes(a.id)));
}
function isGodUnlocked(id){
 if(id==='azathoth')return finalGodReady()&&progress.achievements.includes('azathoth_final');
 return startingGods.has(id)||achievements.some(a=>a.god===id&&progress.achievements.includes(a.id));
}
function isSkillUnlocked(id){return startingSkills.has(id)||achievements.some(a=>a.skill===id&&progress.achievements.includes(a.id))}
// Difficulty unlocks and remembered selection are scoped to a specific mode AND stage.
// Old global win counters remain intact for achievements only; they do not unlock other routes.
function difficultyPairKey(mode=gameMode,stage=selectedStage){return `${mode}_${stage}`}
function clearCount(mode,stage,rank){return Math.max(0,Number(progress.clears?.[`${mode}_${stage}_${rank}`])||0)}
function highestClearedDifficulty(mode,stage){for(const rank of ['nightmare','hard','normal','easy'])if(clearCount(mode,stage,rank)>0)return rank;return null}
function difficultyUnlocked(id,mode=gameMode,stage=selectedStage){
 if(id==='easy'||id==='normal')return true;
 if(id==='hard')return clearCount(mode,stage,'normal')>0||clearCount(mode,stage,'hard')>0||clearCount(mode,stage,'nightmare')>0;
 if(id==='nightmare')return clearCount(mode,stage,'hard')>0||clearCount(mode,stage,'nightmare')>0;
 return false;
}
function syncDifficultyForSelection(){
 const key=difficultyPairKey();const saved=progress.difficultySelections?.[key];
 difficulty=Object.hasOwn(DIFFICULTIES,saved)&&difficultyUnlocked(saved)?saved:'normal';
}
function chooseDifficultyForPair(id){
 if(!difficultyUnlocked(id))return;
 difficulty=id;progress.difficultySelections[difficultyPairKey()]=id;
 saveProgress();renderDifficulty();playSfx('ui_move');
}
function restoreDifficultyFromSave(data){
 const key=difficultyPairKey(),legacy=data?.difficultyPreference;
 if(!Object.keys(progress.difficultySelections).length&&Object.hasOwn(DIFFICULTIES,legacy)&&difficultyUnlocked(legacy))progress.difficultySelections[key]=legacy;
 syncDifficultyForSelection();
}
function renderDifficulty(){
 const area=$('difficultySelect');if(!area)return;
 let context=$('difficultyContext');if(!context){context=document.createElement('div');context.id='difficultyContext';context.className='difficulty-context';area.before(context)}
 context.textContent=`${gameModes[gameMode].name} ／ ${stageDefs[selectedStage].name} の解放状況（この組み合わせだけに適用）`;
 area.replaceChildren();for(const [key,cfg] of Object.entries(DIFFICULTIES)){
  const b=document.createElement('button');b.type='button';b.className='difficulty-button'+(key===difficulty?' selected':'');
  b.disabled=!difficultyUnlocked(key);b.textContent=cfg.name+(b.disabled?' 🔒':'');b.setAttribute('aria-pressed',String(key===difficulty));
  b.title=b.disabled?(key==='hard'?'このモード・ステージのノーマルをクリアで解放':'このモード・ステージのハードをクリアで解放'):`敵HP${Math.round(cfg.enemyHp*100)}%・被ダメージ${Math.round(cfg.enemyDamage*100)}%・敵出現間隔${Math.round(cfg.enemyRate*100)}%`;
  b.onclick=()=>chooseDifficultyForPair(key);area.append(b)
 }
}
function renderAchievements(){const host=$('achievementsList');if(!host)return;host.replaceChildren();
 const top=document.createElement('p');top.className='help';top.textContent=`達成 ${progress.achievements.length}/${achievements.length}　｜　累計撃破 ${progress.kills}体　｜　勝利 ${progress.wins}回　｜　最高Lv.${progress.bestLevel}　｜　難易度解放はモード・ステージごと`;host.append(top);
 for(const a of achievements){const done=progress.achievements.includes(a.id),row=document.createElement('div');row.className='achievement'+(done?'':' locked');
 const unlocks=[a.god?'邪神「'+pantheon[a.god].name+'」':'',a.skill?'スキル「'+(upgradeDefs.find(d=>d.key===a.skill)?.name||a.skill)+'」':''].filter(Boolean).join('・');
 row.innerHTML=`<strong>${done?'✓ ':'🔒 '}${a.name}</strong>　${a.need}<small>報酬：${unlocks}</small>`;host.append(row)
 }
}
function openAchievements(){renderAchievements();$('achievementsOverlay').hidden=false}
function closeAchievements(){$('achievementsOverlay').hidden=true}
$('achievementsClose').onclick=closeAchievements;
$('achievementsOverlay').addEventListener('click',e=>{if(e.target===$('achievementsOverlay'))closeAchievements()});
function checkAchievements(){let changed=false;const awards=[];for(const a of achievements){if(!progress.achievements.includes(a.id)&&a.when(progress)){
 progress.achievements.push(a.id);changed=true;awards.push(a.name)
 }}if(changed){saveProgress();if(game==='play')toast('実績解除：'+awards.join('・'));renderDifficulty()}
 return awards
}


// Portable permanent-progression save. This is deliberately NOT an in-progress run save.
const SAVE_FILE_APP='maremon-survivors';
const SAVE_FILE_VERSION=1;
function cleanProgress(data){
 if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('セーブ内容が不正です。');
 if(!Number.isSafeInteger(data.kills)||!Number.isSafeInteger(data.runs))throw new Error('対応していないセーブ内容です。');
 const fresh=newProgress();
 for(const key of Object.keys(fresh)){
  if(['achievements','clears','enemyKills','stageEnemyKills','patronBoosts','difficultySelections'].includes(key))continue;
  const v=data[key];if(v===undefined)continue;
  if(!Number.isSafeInteger(v)||v<0||v>1e12)throw new Error('記録の数値が不正です：'+key);
  fresh[key]=key==='bestLevel'?Math.max(1,v):v;
 }
 if(data.achievements!==undefined){
  if(!Array.isArray(data.achievements)||data.achievements.length>200)throw new Error('実績データが不正です。');
  fresh.achievements=[...new Set(data.achievements.filter(id=>typeof id==='string'&&achievements.some(a=>a.id===id)))];
 }
 for(const field of ['enemyKills','stageEnemyKills','patronBoosts']){
  if(data[field]===undefined)continue;
  if(!data[field]||typeof data[field]!=='object'||Array.isArray(data[field]))throw new Error(field+' の内容が不正です。');
  const rows=Object.entries(data[field]);if(rows.length>100)throw new Error('記録の項目数が多すぎます。');
  for(const [key,value] of rows){
   if(!/^[a-z_]{2,48}$/.test(key)||!Number.isSafeInteger(value)||value<0||value>1e9)throw new Error('記録の数値が不正です：'+field);
   Object.defineProperty(fresh[field],key,{value,enumerable:true,writable:true,configurable:true});
  }
 }
 if(data.clears!==undefined){
  if(!data.clears||typeof data.clears!=='object'||Array.isArray(data.clears))throw new Error('クリア記録が不正です。');
  fresh.clears={};
  for(const [key,count] of Object.entries(data.clears)){
   if(!/^(expedition|survival)_(ruins|rlyeh|innsmouth|blackwood|ashchapel)_(easy|normal|hard|nightmare)$/.test(key))continue;
   if(!Number.isSafeInteger(count)||count<0||count>1e9)throw new Error('クリア回数が不正です。');
   Object.defineProperty(fresh.clears,key,{value:count,enumerable:true,writable:true,configurable:true});
  }
 }
 if(data.difficultySelections!==undefined){
  if(!data.difficultySelections||typeof data.difficultySelections!=='object'||Array.isArray(data.difficultySelections))throw new Error('難易度設定が不正です。');
  fresh.difficultySelections={};
  const entries=Object.entries(data.difficultySelections);if(entries.length>10)throw new Error('難易度設定が多すぎます。');
  for(const [key,value] of entries){
   if(!/^(expedition|survival)_(ruins|rlyeh|innsmouth|blackwood|ashchapel)$/.test(key))continue;
   if(!Object.hasOwn(DIFFICULTIES,value))throw new Error('難易度設定が不正です。');
   Object.defineProperty(fresh.difficultySelections,key,{value,enumerable:true,writable:true,configurable:true});
  }
 }
 return fresh;
}
function saveNotice(message,isError=false){const e=$('saveStatus');if(e){e.textContent=message;e.style.color=isError?'#ffaeb3':'#b9efcd'}}
function exportProgressFile(){
 try{
  saveProgress();
  const data={app:SAVE_FILE_APP,formatVersion:SAVE_FILE_VERSION,exportedAt:new Date().toISOString(),progress:cleanProgress(progress),difficultyPreference:difficulty};
  const blob=new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json;charset=utf-8'});
  const url=URL.createObjectURL(blob),link=document.createElement('a');
  link.href=url;link.download='maremon_save_'+new Date().toISOString().slice(0,10)+'.json';
  document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
  saveNotice('JSONを書き出しました。ダウンロードしたファイルを保管してください。');
 }catch(err){saveNotice('書き出し失敗：'+err.message,true)}
}
async function importProgressFile(file){
 if(!file)return;
 try{
  if(file.size>262144)throw new Error('ファイルが大きすぎます（256KBまで）。');
  const data=JSON.parse(await file.text());
  if(data.app!==SAVE_FILE_APP||data.formatVersion!==SAVE_FILE_VERSION)throw new Error('マレモンの対応セーブJSONではありません。');
  const incoming=cleanProgress(data.progress);
  if(!confirm('現在の実績・解放状況を、選択したセーブ内容で上書きします。続行しますか？')){
   saveNotice('読み込みをキャンセルしました。');return;
  }
  progress=incoming;
  restoreDifficultyFromSave(data);
  if(!isGodUnlocked(patron))patron='cthulhu';
  checkAchievements();
  const persisted=saveProgress();
  renderAchievements();renderOptions();
  saveNotice(persisted?'読み込み完了：実績・解放状況を復元しました。':'読み込みましたが自動保存に失敗しました。JSONを保管してください。',!persisted);
  if($('bootActions'))showTitle();
 }catch(err){saveNotice('読み込み失敗：'+(err instanceof SyntaxError?'JSON形式が正しくありません。':err.message),true)}
 finally{$('saveFile').value=''}
}

$('saveFileLocation').addEventListener('click',async()=>{
 try{await chooseSaveFile();if($('bootStatus'))$('bootStatus').textContent='セーブの読み込みと保存先設定が完了しました。';}
 catch(err){if(err.name!=='AbortError')saveNotice('保存先の設定失敗：'+err.message,true)}
});
$('saveFileNow').addEventListener('click',async()=>{
 if(saveFileHandle&&saveReady){await flushSaveFile(true)}
 else if(saveFileHandle){try{await activateSaveHandle(saveFileHandle);await flushSaveFile(true)}catch(e){saveNotice(e.message,true)}}
 else if(typeof window.showSaveFilePicker==='function'){try{await chooseSaveFile()}catch(e){if(e.name!=='AbortError')saveNotice(e.message,true)}}
 else exportProgressFile();
});
$('saveExport').addEventListener('click',exportProgressFile);
$('saveImportButton').addEventListener('click',()=>$('saveFile').click());
$('saveFile').addEventListener('change',e=>{const file=e.target.files[0];importProgressFile(file)});
$('saveClose').addEventListener('click',()=>$('saveOverlay').hidden=true);
$('saveOverlay').addEventListener('click',e=>{if(e.target===$('saveOverlay'))$('saveOverlay').hidden=true});
function openSaveManager(){updateSaveLocation();$('saveOverlay').hidden=false}

let gameMode='expedition';
const gameModes={expedition:{name:'エリア攻略',desc:'6つの戦闘エリアを攻略。必要Lvで門が開き、その部屋の育成報酬は終了。最深部は取り巻きなしのボス戦。'},survival:{name:'サバイバル',desc:'30分間、押し寄せる異端と神話生物の大群を生き延びる。'}};
// Six combat chambers plus one boss chamber. The boss chamber is reached only after clearing all six.
// The clock is informational in expedition; room progression, not time, drives enemy difficulty.
// Each chamber opens only after reaching the required leader level.
const gateLevels=[4,7,10,13,16,19];
const COMBAT_ROOMS=gateLevels.length, TOTAL_ROOMS=COMBAT_ROOMS+1;
// Anti-farm: the current combat room becomes exhausted once its level gate is reached.
// This limits reward growth without a compulsory timer or invalidating defensive builds.
function roomRewardsOpen(){return gameMode!=='expedition'||regionIndex>=COMBAT_ROOMS||(!completedRooms[regionIndex]&&level<gateLevels[regionIndex])}


// Pilot-stage XP: reward location and collection matter. Other stages retain v405 experience rules.
let ruinsXpDrops=[],ruinsWaveTimer=9,ruinsWaveCount=0;
function addRuinsXp(x,y,value){
 if(value<=0)return;
 if(ruinsXpDrops.length>=230){const near=ruinsXpDrops[(Math.abs(Math.floor(x+y))%ruinsXpDrops.length)];near.value+=value;return;}
 const scatter=ruinsXpDrops.length%7;
 ruinsXpDrops.push({x:x+Math.cos(scatter*2.4)*11,y:y+Math.sin(scatter*2.4)*11,value,life:90,pull:0,seed:Math.random()*6.3});
}
function updateRuinsXp(dt){
 if(selectedStage!=='ruins')return;
 const range=51*(1+up.magnet*.10+up.recruit*.025),vacuum=170*(1+up.magnet*.08);
 for(let i=ruinsXpDrops.length-1;i>=0;i--){
  const g=ruinsXpDrops[i];g.life-=dt;
  const dx=player.x-g.x,dy=player.y-g.y,dist=Math.hypot(dx,dy);
  if(dist<vacuum||g.pull>0){g.pull=1;const step=Math.min(dist,(190+Math.max(0,vacuum-dist)*2)*dt);if(dist>0){g.x+=dx/dist*step;g.y+=dy/dist*step}}
  if(dist<range*.63||g.pull>0&&dist<20){xp+=g.value;ruinsXpDrops.splice(i,1);}
  else if(g.life<=0)ruinsXpDrops.splice(i,1);
 }
}
function drawRuinsXp(){
 if(selectedStage!=='ruins'||!ruinsXpDrops.length)return;
 const im=environmentArt.xp_ruins_crystal;if(!im||!im.complete||!im.naturalWidth)return;
 for(const g of ruinsXpDrops){const x=g.x-camera.x+W/2,y=g.y-camera.y+H/2;
  if(x<-32||y<-32||x>W+32||y>H+32)continue;
  const size=g.value>=12?30:g.value>=4?25:20,bob=Math.sin(time*5+g.seed)*1.7;
  ctx.save();ctx.shadowColor='#5abffc';ctx.shadowBlur=5;ctx.globalAlpha=.94;ctx.drawImage(im,x-size/2,y-size/2+bob,size,size);ctx.restore();
 }
}
const ruinsWavePlans=[
 {kind:'siege',units:['zealot','ghoul'],count:11},
 {kind:'pincer',units:['zealot','archer','ghoul'],count:14},
 {kind:'rush',units:['ghoul','nameless_reptile'],count:15},
 {kind:'spear',units:['nameless_reptile','fanatic','priest'],count:13},
 {kind:'pincer',units:['nameless_reptile','migo','archer'],count:16},
 {kind:'siege',units:['nameless_reptile','migo','priest'],count:18}
];
function spawnRuinsWave(dt){
 if(selectedStage!=='ruins'||game!=='play'||gameMode==='expedition'&&(regionIndex>=COMBAT_ROOMS||expeditionHallway||!roomRewardsOpen()))return;
 ruinsWaveTimer-=dt;if(ruinsWaveTimer>0)return;
 const index=gameMode==='expedition'?regionIndex:Math.min(5,Math.floor(time/260));
 const plan=ruinsWavePlans[index],maxSpawn=Math.min(26,plan.count+Math.min(4,ruinsWaveCount%5));
 const base=ruinsWaveCount++%4,edgeDirections=[[-1,0],[1,0],[0,-1],[0,1]];
 for(let i=0;i<maxSpawn&&enemies.length<157;i++){
  const edge=plan.kind==='pincer'?(i%2?base:(base+2)%4):plan.kind==='siege'?(base+i%4)%4:base;
  const [dx,dy]=edgeDirections[edge];const from={x:camera.x+dx*(W/2+240),y:camera.y+dy*(H/2+240)};
  spawnEnemy(false,plan.units[(i+ruinsWaveCount)%plan.units.length],from);
 }
 ruinsWaveTimer=(gameMode==='expedition'?12.5:14.5)*DIFFICULTIES[difficulty].enemyRate;
}

