  const k=bgm.transition/bgm.duration;
  bgm.active.volume=Math.min(1,Math.max(0,volumeFor(bgm.active)*k));
  if(bgm.outgoing){bgm.outgoing.volume=Math.min(1,Math.max(0,volumeFor(bgm.outgoing)*(1-k)));if(k>=1){bgm.outgoing.pause();bgm.outgoing.src='';bgm.outgoing=null}}
