// Skills and followers act on enemies whose bodies are actually inside the player's view.
// Using the current camera (not an arbitrary distance from the player) also works on narrow screens.
function onScreen(o,margin=16){
 if(!o||!Number.isFinite(o.x)||!Number.isFinite(o.y))return false;
 const x=o.x-camera.x+W/2,y=o.y-camera.y+H/2;
 return x>=margin&&x<=W-margin&&y>=margin&&y<=H-margin;
}
function visibleTargets(origin=player,range=Infinity,limit=Infinity){
 const rangeSq=range*range;
 return enemies.filter(e=>!e.dead&&onScreen(e)&&(!origin||dist2(e,origin)<=rangeSq))
  .sort((a,b)=>(origin?dist2(a,origin)-dist2(b,origin):a.id-b.id)).slice(0,limit);
}
