// A shared scheduler, not a shared attack: each case below has its own combat logic.
function performPatronArt(id,rank=1,empowered=false){
 if(!player||!patronArts[id])return 0;
 const a=patronArts[id],color=a.color,seen=new Set();let count=0;
 const targets=visibleTargets(player,empowered?490:410,Math.min(8,2+rank+(empowered?2:0)));
 const bossEnemy=e=>e.kind&&e.kind.startsWith('rival');
 const hit=(e,dmg,source='patron-art')=>{if(e.dead||!onScreen(e)||seen.has(e.id))return false;seen.add(e.id);damageEnemy(e,dmg*(empowered?1.65:1),source);count++;return true};
 const mark=(e,sz=40)=>{addSigil(e.x,e.y,color,sz,1.1);};
 const n=Math.max(1,rank);
 switch(id){
  case 'vulthoom':
   for(const e of targets){e.webbed=Math.max(e.webbed||0,bossEnemy(e)?0:1.4+n*.35);e.slow=Math.max(e.slow||0,1.4+n*.35);e.poison=Math.max(e.poison||0,3);e.poisonDamage=Math.max(e.poisonDamage||0,n*.5);mark(e,44);count++}break;
  case 'daoloth':
   for(const e of targets){addRay(player.x,player.y,e.x,e.y,color,{target:e,damage:2+n*1.7+(empowered?3:0),source:'patron-art',credit:empowered});mark(e,24);if(!empowered)count++}break;
  case 'tsathoggua':
   for(const e of targets)if(hit(e,2+n*.9)){boost=Math.min(100,boost+1.5);mark(e,34)}break;
  case 'azathoth':
   for(const e of targets.slice(0,Math.max(1,Math.ceil(targets.length/2)))){
    addSigil(e.x,e.y,color,60);for(const other of enemies)if(!other.dead&&onScreen(other)&&dist2(other,e)<60*60)hit(other,1.5+n*.75);
   }break;
  case 'atlach':
   for(const e of targets){e.slow=Math.max(e.slow||0,2+n*.35);hit(e,2+n*.4);mark(e,37)}break;
  case 'ghatanothoa':
   for(const e of targets){if(bossEnemy(e))e.slow=Math.max(e.slow||0,1.6);else e.stone=Math.max(e.stone||0,2+n*.35);hit(e,1+n*.4);mark(e,40)}break;
  case 'ithaqa':
   addSigil(player.x,player.y,color,160+n*14,1.2);
   for(const e of enemies){if(!e.dead&&onScreen(e)&&dist2(e,player)<(160+n*14)**2){e.slow=Math.max(e.slow||0,2);hit(e,1.5+n*.6)}}break;
  case 'yig':
   for(const e of targets){e.poison=Math.max(e.poison||0,4);e.poisonDamage=Math.max(e.poisonDamage||0,.8+n*.45);hit(e,1+n*.3);mark(e)}break;
  case 'ubbo':
   for(const e of targets){hit(e,1+n*.75);mark(e,30)}
   patronArtPulses++;if(patronArtPulses%2===0)makeFollower();break;
  case 'chaugnar':
   for(const e of targets){if(hit(e,2+n*.8)){player.hp=Math.min(player.maxHp,player.hp+(empowered?2:1));mark(e,25)}}break;
  case 'rlim':
   for(const e of targets){if(bossEnemy(e))e.slow=Math.max(e.slow||0,2);else e.webbed=Math.max(e.webbed||0,1.1+n*.3);hit(e,1+n*.7);mark(e,32)}break;
  case 'shudde':
   addSigil(player.x,player.y,color,160+n*16,1.2);
   for(const e of enemies)if(!e.dead&&onScreen(e)&&dist2(e,player)<(160+n*16)**2){e.attack=Math.max(e.attack||0,.6);hit(e,2+n*.6)}break;
  case 'gloon':
   for(const e of targets){confuseEnemy(e,1.7+n*.45);e.gloonMark=Math.max(e.gloonMark||0,1.7+n*.45);hit(e,.5+n*.25);mark(e,30)}break;
  case 'yibb':
   patronWardTime=Math.max(patronWardTime,3+n*.45);patronWardStrength=(10+n*3)/100;
   addSigil(player.x,player.y,color,120,1.3);
   for(const e of enemies)if(!e.dead&&onScreen(e)&&dist2(e,player)<170*170)hit(e,1+n*.5);break;
  case 'cthugha':
   for(const e of targets.slice(0,Math.ceil(targets.length/2))){
    mark(e,60);for(const other of enemies)if(!other.dead&&onScreen(other)&&dist2(other,e)<60*60){other.poison=Math.max(other.poison||0,3);other.poisonDamage=Math.max(other.poisonDamage||0,.5+n*.3);hit(other,2+n*.7)}
   }break;
  case 'mhithrha':
   for(const e of targets){e.slow=Math.max(e.slow||0,1.5);addRay(player.x,player.y,e.x,e.y,color,{target:e,damage:2+n*1.1+(empowered?2:0),source:'tindalos',credit:empowered});mark(e,40);if(!empowered)count++}break;
 }
 if(count>0||id==='daoloth'||id==='mhithrha')playSfx('god_'+id+'_skill');
 if(empowered&&id!=='daoloth'&&id!=='mhithrha')boostProgressGain(count);
 return count;
}
function tickPatronArt(dt){
 if(!player||!patronArts[patron])return;
 patronWardTime=Math.max(0,patronWardTime-dt);
 const n=myth[patron]||0;
 if(n>0&&mythClock[patron]<=0){
  const hitCount=performPatronArt(patron,n,false);
  mythClock[patron]=hitCount>0||patron==='yibb'?Math.max(5,patronArts[patron].cooldown-n*(patronArts[patron].cooldown===17?1.4:patronArts[patron].cooldown===15||patronArts[patron].cooldown===14||patronArts[patron].cooldown===13?1.2:.9)):2;
 }
}
function tickPatronBoost(dt){
 boostPulseClock-=dt;if(boostPulseClock>0)return;
 boostPulseClock=1.02;boostPulseCount++;
 performPatronArt(patron,Math.max(3,myth[patron]||0),true);
}

