let followerEvoRanks=Object.create(null),followerEvoDirty=false;
function followerCounts(){
 const c={raider:0,guardian:0,hunter:0};
 for(const f of followers)if(!f.eliteForm&&f.role in c)c[f.role]++;
 return c;
}
function followerEvoCanBuy(def,counts=followerCounts()){
 return Object.entries(def.need).every(([role,n])=>(counts[role]||0)>=n);
}
function followerEvoEligible(){const counts=followerCounts();return followerEvoDefs.filter(def=>followerEvoCanBuy(def,counts))}
// Elite assignment is permanent until the individual leaves; recruiting never creates free elites.
function refreshFollowerEvolutions(){followerEvoDirty=false}
function selectFollowerEvolution(def){
 if(game!=='level'||!def||!followerEvoCanBuy(def))return false;
 const spent=[];
 for(const [role,n] of Object.entries(def.need)){
  const group=followers.filter(f=>!f.eliteForm&&f.role===role).slice(-n);
  if(group.length!==n)return false;
  spent.push(...group);
 }
 // One member is transformed into the elite and the other consumed members leave play.
 // This yields exactly one elite and reduces the congregation by cost minus one.
 const host=spent.find(f=>f.role===def.role)||spent[0];
 const erased=new Set(spent.filter(f=>f!==host));
 for(let i=followers.length-1;i>=0;i--)if(erased.has(followers[i]))followers.splice(i,1);
 host.role=def.role;host.eliteForm=def.key;host.eliteHits=0;host.target=null;
 host.phase='ready';host.phaseTimer=0;host.attack=0;host.shot=0;host.scan=0;
 followerEvoRanks[def.key]=(followerEvoRanks[def.key]||0)+1;
 followerEvoDirty=false;
 playSfx('evolution');addSigil(host.x,host.y,def.color,110);puff(host.x,host.y,def.color,12);
 game='play';$('levelpanel').style.display='none';
 const cost=spent.length;
 toast(`信者進化《${def.name}》：通常信者${cost}人→上位信者1人（総人数−${cost-1}人）。`);
 updateHud();
 return true;
}
function renderFollowerEvoOffer(){
 const holder=$('followerEvoOffers'),box=$('followerEvoCard'),available=followerEvoEligible();
 holder.hidden=available.length===0;box.replaceChildren();
 if(!available.length)return;
 // Every currently affordable recipe is its own independent selectable card.
 for(const def of available){
  const b=document.createElement('button');b.type='button';b.className='card evolution';b.style.borderColor=def.color;
  const tag=document.createElement('span');tag.className='tag';tag.textContent='信者進化（スキル枠消費なし）';
  const title=document.createElement('b');title.textContent=def.name;
  const detail=document.createElement('span');detail.textContent=def.bonus;
  const small=document.createElement('small');
  const cost=Object.values(def.need).reduce((a,b)=>a+b,0);
  const done=followers.filter(f=>f.eliteForm===def.key).length;
  small.textContent=`必要：通常信者${cost}人 ／ 所持の《${def.name}》${done}人 ／ 今回の進化で1人生成`;
  b.append(tag,title,detail,small);b.onclick=()=>selectFollowerEvolution(def);box.append(b);
 }
}

function chooseRole(){const total=Object.values(roleWeight).reduce((a,b)=>a+b,0);let r=Math.random()*total;for(const role of ["raider","guardian","hunter"]){r-=roleWeight[role];if(r<0)return role}return "hunter"}
function rebalanceRoles(){
 // Rebalance in linear time; unlike the old nested filters this stays responsive
 // when the congregation grows beyond hundreds of followers.
 const roles=['raider','guardian','hunter'];
 const normalMembers=followers.filter(f=>!f.eliteForm);
 const total=Math.max(1,roles.reduce((a,r)=>a+Math.max(0,roleWeight[r]||0),0));
 const goal=Object.fromEntries(roles.map(r=>[r,Math.floor(normalMembers.length*Math.max(0,roleWeight[r]||0)/total)]));
 let unassigned=normalMembers.length-roles.reduce((a,r)=>a+goal[r],0);
 for(const r of [...roles].sort((a,b)=>roleWeight[b]-roleWeight[a]))if(unassigned-- >0)goal[r]++;
 const count={raider:0,guardian:0,hunter:0};
 const surplus=[];
 for(const f of normalMembers){if(!(f.role in count))f.role='hunter';count[f.role]++;}
 for(const f of normalMembers){if(count[f.role]>goal[f.role]){count[f.role]--;surplus.push(f)}}
 let i=0;
 for(const r of roles)while(count[r]<goal[r]&&i<surplus.length){
   const f=surplus[i++];f.role=r;f.target=null;f.phase='ready';count[r]++;
 }
 followerEvoDirty=true;
}

