const tierRoster=[
 [0,['zealot']],
 [85,['zealot','fanatic']],
 [210,['zealot','fanatic','ghoul']],
 [360,['zealot','fanatic','ghoul','archer']],
 [540,['zealot','fanatic','ghoul','archer','bulwark','deepone']],
 [780,['zealot','fanatic','ghoul','archer','bulwark','deepone','priest']],
 [1020,['zealot','fanatic','ghoul','archer','bulwark','deepone','priest','migo']],
 [1300,['zealot','fanatic','ghoul','archer','bulwark','deepone','priest','migo','byakhee']]
];
function getRoster(){let pool=tierRoster[0][1];for(const [t,p] of tierRoster){if(threatClock()>=t)pool=p;else break}return pool}
function spawnEnemy(initial=false,forcedKind=null,spawnPoint=null){
 if(gameMode==='expedition'&&regionIndex===COMBAT_ROOMS&&!(forcedKind||'').startsWith('rival'))return null;
 if(enemies.length>=185)return null;
 const pool=getRoster(),stageEnemy=gameMode==='expedition'?expeditionRoomEnemies[selectedStage][regionIndex]:stageDefs[selectedStage].enemy;
 const mapWeight=gameMode==='expedition'?Math.min(.87,.51+regionIndex*.06):.37;
 const kind=forcedKind||(((gameMode==='expedition'||threatClock()>100)&&Math.random()<mapWeight)?stageEnemy[Math.floor(Math.random()*stageEnemy.length)]:pool[Math.floor(Math.random()*pool.length)]),def=enemyDefs[kind];
 if(!def)return null;
 let p=spawnOutsideView(def.r,spawnPoint);if(!p)return null;for(let attempt=0;attempt<9&&solidAt(p.x,p.y,def.r);attempt++){p=spawnOutsideView(def.r,spawnPoint);if(!p)return null}const scale=1+(gameMode==='survival'?Math.min(3.2,time*.0017):threatClock()*.0038);
 const isBoss=kind.startsWith('rival');const hp=isBoss?def.hp*(gameMode==='expedition'?5:9)*DIFFICULTIES[difficulty].bossHp:def.hp*scale*(gameMode==='expedition'?1+regionIndex*.20:1)*DIFFICULTIES[difficulty].enemyHp;
 const e={...p,id:++enemyId,kind,hp,maxHp:hp,r:def.r,speed:def.speed*(1+Math.min(.23,threatClock()*(gameMode==='survival'?.00017:.0012))),damage:(def.dmg+Math.floor(threatClock()/(gameMode==='survival'?360:100)))*DIFFICULTIES[difficulty].enemyDamage,attack:rnd(.2,1.2),cast:rnd(1.4,3),flash:0,slow:0,confused:0,dead:false,charge:0,chargeX:0,chargeY:0,chargeCd:rnd(2.5,4.5),phase:rnd(0,6.28)};
 enemies.push(e);
 if(kind.startsWith('rival'))boss=e;
 if(!seenTypes.has(kind)){seenTypes.add(kind);if(!initial)toast(kind.startsWith('rival')?'⚜ 異端の首領が現れた！':def.name+' が出現！')}
 return e;
}
function spawnElite(){
 if(enemies.length>=166){let removed=0;for(let i=enemies.length-1;i>=0&&enemies.length>162;i--){if(enemies[i]!==boss&&!enemies[i].elite){enemies.splice(i,1);removed++}}}
 const kinds=['fanatic','bulwark','priest','migo'];
 const kind=kinds[Math.min(nextElite-1,kinds.length-1)];
 const e=spawnEnemy(false,kind);
 if(!e)return;
 e.elite=true;e.maxHp*=5.7;e.hp=e.maxHp;e.r+=5;e.damage+=3;e.speed*=.9;
 toast('異端の強敵が現れた！');playSfx('boss_warning');
 return e;
}

