function enhanceSetupLayout(){
 const host=$('box');if(!host||host.querySelector('.setup-flow'))return;
 const page=document.createElement('div');page.className='setup-flow';
 const createSection=(number,title,note,ids)=>{
  const section=document.createElement('section');section.className='setup-section';
  section.innerHTML=`<div class="setup-section-heading"><span class="setup-index">${number}</span><div><h2>${title}</h2><p>${note}</p></div></div>`;
  for(const id of ids){const e=$(id);if(e)section.append(e)}page.append(section);return section;
 };
 const configuration=createSection('01','挑戦内容を決める','モード・ステージを選び、その組み合わせの難易度を設定',['modeSelect','stageSelect','difficultySelect']);
 for(const [id,title] of [['modeSelect','ゲームモード'],['stageSelect','舞台'],['difficultySelect','難易度']]){
   const target=configuration.querySelector('#'+id);if(!target)continue;const p=document.createElement('div');p.className='setup-field-title';p.textContent=title;target.before(p);
 }
 const summary=document.createElement('div');summary.id='setupSummary';summary.className='setup-summary';configuration.append(summary);
 createSection('02','教義を配分する','10ポイントを振り分けて初期の戦い方を決める',['options','risk']);
 createSection('03','神格を選ぶ','信仰する神格で星辰ブーストと固有能力が変わる',['patrons','patronEffect']);
 const details=document.createElement('details');details.className='setup-help';details.innerHTML='<summary>操作方法・基本ルールを確認</summary>';
 for(const p of [...host.querySelectorAll(':scope > p')]){
  const t=p.textContent.trim();
  if(/挑戦するモード|難易度（|探索する舞台|信仰する神格|神格のみ選択可能/.test(t)){p.remove();continue}
  if(p.id==='risk'||p.classList.contains('sub'))continue;
  if(p.classList.contains('help')||p.classList.contains('guide'))details.append(p);
 }
 page.append(details);
 const footer=document.createElement('div');footer.className='setup-footer';
 footer.append($('backTitle'),$('start'));page.append(footer);
 host.append(page);
 // A single delegated event keeps the summary synchronized with all original selection buttons.
 page.addEventListener('click',()=>queueMicrotask(updateSetupSummary));
 updateSetupSummary();
}
