// The selectable card describes the AFTER level only; underline only changed numerical values.
// Unchanged values (such as fixed damage multipliers or effect durations) stay neutral.
function renderEffectChange(previous,after,showDifference){
 const frag=document.createDocumentFragment();
 if(!showDifference){frag.append(document.createTextNode(after));return frag}
 const beforeNumbers=Array.from(previous.matchAll(/\d+(?:\.\d+)?/g),m=>m[0]);
 let last=0,i=0;
 for(const match of after.matchAll(/\d+(?:\.\d+)?/g)){
  const n=match[0],offset=match.index;
  if(offset>last)frag.append(document.createTextNode(after.slice(last,offset)));
  if(beforeNumbers[i]!==n){
   const changed=document.createElement('mark');changed.className='effect-change';
   changed.textContent=n;changed.title='今回変化する数値';frag.append(changed);
  }else frag.append(document.createTextNode(n));
  last=offset+n.length;i++;
 }
 if(last<after.length)frag.append(document.createTextNode(after.slice(last)));
 return frag;
}
