 const ownedMyth=mythSkills.filter(d=>(!d.patronOnly||d.patronOnly===patron)&&myth[d.key]>0&&myth[d.key]<d.max).map(def=>({type:'myth',def}));
 const regularUsed=upgradeDefs.filter(d=>!d.type&&upgradeLevel(d)>0).length;
 const mythUsed=mythSkills.filter(d=>myth[d.key]>0).length;
 const newNormal=regularUsed<COMMON_SLOTS?upgradeDefs.filter(d=>!d.type&&upgradeLevel(d)===0&&isSkillUnlocked(d.key)).map(def=>({type:'ordinary',def})):[];
 const newMyth=mythUsed<MYTH_SLOTS?mythSkills.filter(d=>(!d.patronOnly||d.patronOnly===patron)&&myth[d.key]===0).map(def=>({type:'myth',def})):[];
 const instantRewards=upgradeDefs.filter(d=>d.type==='instant'&&upgradeLevel(d)<d.max).map(def=>({type:'instant',def}));
 const existing=[...ownedNormal,...ownedMyth],unlearned=[...newNormal,...newMyth],picks=[];
 $('slotInfo').textContent=`通常スキル ${regularUsed}/${COMMON_SLOTS}　｜　神話スキル ${mythUsed}/${MYTH_SLOTS}　｜　引き直し ${rerolls}回`;
 function pick(pool){const rest=pool.filter(o=>!picks.some(p=>p.def===o.def));if(!rest.length)return false;const selected=rest[Math.floor(Math.random()*rest.length)];picks.push(selected);return true}
 // Prioritize an owned skill but always provide a chance to open new branches.
 if(existing.length){const previous=existing.find(o=>lastChosen&&o.def.key===lastChosen.key&&o.type===lastChosen.type);if(previous&&Math.random()<.65)picks.push(previous);else pick(existing)}
 if(picks.length<3&&newMyth.length&&mythUsed===0&&Math.random()<.75)pick(newMyth.filter(o=>o.def.key===patron));if(picks.length<3&&unlearned.length)pick(unlearned);
 if(picks.length<3&&Math.random()<.30)pick(instantRewards);if(picks.length<3&&existing.length>=2)pick(existing);
 while(picks.length<3&&(pick(existing)||pick(unlearned)||pick(instantRewards))){}
 if(!picks.length){const b=document.createElement('button');b.className='card';b.innerHTML='<b>ひとときの休息</b><span>HPを30回復する。</span>';b.onclick=()=>{player.hp=Math.min(player.maxHp,player.hp+30);playSfx('upgrade');game='play';$('levelpanel').style.display='none'};cards.append(b)}
 else for(const {type,def} of picks){
  const current=type==='myth'?myth[def.key]:upgradeLevel(def),next=current+1;
  const b=document.createElement('button');b.className='card '+(type==='myth'?'myth':'');
  const label=type==='instant'?'即時報酬（枠を消費しない）':current===0?'新規習得':`Lv.${current} → ${next}`;
   const desc=type==='myth'?def.desc(next):def.description(next);
   const prior=current>0?(type==='myth'?def.desc(current):def.description(current)):'';
  b.innerHTML=`<span class="tag">${type==='myth'?'✧ 神話':type==='instant'?'♟ 信者の増援':'✦ 通常スキル'} ・ ${label}</span><b>${type==='myth'?mythGlyph[def.key]+' ':''}${def.name}</b><span class="effect-description"></span><small>${type==='instant'?'スキル枠の消費なし':`Lv.${next} / ${def.max}`}</small>`;
   b.querySelector('.effect-description').append(renderEffectChange(prior,desc,current>0&&type!=='instant'));
  b.onclick=()=>{if(type==='myth')upgradeMyth(def);else takeUpgrade(def);playSfx(type==='instant'?'recruit':'upgrade');lastChosen={type,key:def.key};game='play';$('levelpanel').style.display='none';toast(type==='instant'?`${def.name}！`:`${def.name}　Lv.${next}！`);updateHud()};cards.append(b)
 }
 let bt=$('reroll');if(!bt){bt=document.createElement('button');bt.id='reroll';bt.type='button';bt.className='reroll-button';$('levelbox').append(bt)}
 bt.textContent=`啓示を引き直す（残り ${rerolls} 回）`;bt.disabled=rerolls===0||!picks.length;
 bt.onclick=()=>{if(rerolls<=0)return;rerolls--;playSfx('ui_reroll');renderLevelCards()};
 renderFollowerEvoOffer();
 // Skip discards exactly the currently offered reward, without storing or granting it.
 let skip=$('skipReward');if(!skip){skip=document.createElement('button');skip.id='skipReward';skip.type='button';skip.className='reroll-button';skip.style.cssText='background:#242535;border-color:#7b7289;color:#e0dae7;margin-top:8px';$('levelbox').append(skip)}
