function slowTerrain(x,y){const a=Math.floor(x/POOL_CELL),b=Math.floor(y/POOL_CELL);for(let da=-1;da<=1;da++)for(let db=-1;db<=1;db++){
 const pool=poolAt(a+da,b+db);if(pool&&(x-pool.x)**2+(y-pool.y)**2<pool.r**2)return selectedStage==='ruins'?.87:selectedStage==='rlyeh'?.62:selectedStage==='blackwood'?.88:selectedStage==='ashchapel'?.85:.76;
}return 1}
// Resolve movement against solid scenery with wall sliding and deterministic AI detours.
function moveTerrain(actor,dx,dy,r=10){if(!dx&&!dy)return;
 if(!solidAt(actor.x+dx,actor.y+dy,r)){actor.x+=dx;actor.y+=dy;return}
 let moved=false;
 if(!solidAt(actor.x+dx,actor.y,r)){actor.x+=dx;moved=true}
 if(!solidAt(actor.x,actor.y+dy,r)){actor.y+=dy;moved=true}
 if(moved)return;
 // Units automatically skirt a wall instead of repeatedly pushing directly against it.
 if(actor!==player){const len=Math.hypot(dx,dy)||1,side=(actor.id||1)%2?1:-1;
  const trials=[[-dy*side,dx*side],[dy*side,-dx*side],[-dy*.5+dx*.5,dx*.5+dy*.5],[dy*.5+dx*.5,-dx*.5+dy*.5]];
  for(const [tx,ty] of trials){let step=Math.hypot(tx,ty)||1;let xx=actor.x+tx/step*len,yy=actor.y+ty/step*len;
   if(!solidAt(xx,yy,r)){actor.x=xx;actor.y=yy;return}
  }
 }
}
