addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k===' '&&!e.repeat)triggerBoost();if(k==='i'&&!e.repeat&&game==='play')openArtifactPanel();if(k==='escape'&&!e.repeat&&game==='artifact')closeArtifactPanel();if(k==='p'&&game==='play'&&!e.repeat){paused=!paused;syncMusicPause()}});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);pointer=null});const touchPad=$('touchStick'),touchKnob=$('touchStickKnob'),boostButton=$('mobileBoost');
function resetJoystick(){pointer=null;touchKnob.style.transform='translate(0px,0px)';touchPad.style.opacity='1'}
canvas.addEventListener('pointerdown',e=>{if(pointer)return;const isTouch=e.pointerType==='touch'||e.pointerType==='pen';pointer={id:e.pointerId,x:e.clientX,y:e.clientY,originX:e.clientX,originY:e.clientY,touch:isTouch};canvas.setPointerCapture(e.pointerId);if(isTouch){touchPad.style.left=Math.max(9,Math.min(innerWidth-124,e.clientX-56))+'px';touchPad.style.top=Math.max(9,Math.min(innerHeight-124,e.clientY-56))+'px';touchPad.style.bottom='auto';touchPad.style.opacity='1'}});
canvas.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;pointer.x=e.clientX;pointer.y=e.clientY;if(pointer.touch){const dx=e.clientX-pointer.originX,dy=e.clientY-pointer.originY,len=Math.hypot(dx,dy)||1,scale=Math.min(38,len)/len;touchKnob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`}});
canvas.addEventListener('pointerup',e=>{if(pointer?.id===e.pointerId)resetJoystick()});canvas.addEventListener('pointercancel',e=>{if(pointer?.id===e.pointerId)resetJoystick()});
boostButton.addEventListener('pointerdown',e=>e.stopPropagation());boostButton.addEventListener('click',e=>{e.preventDefault();triggerBoost()});
function frame(now){const dt=Math.min(.033,Math.max(0,(now-last)/1000));last=now;try{if(game==='play'&&!paused)step(dt);musicTick(dt);if(boostButton){const ready=game==='play'&&!paused&&boost>=100&&boostState==='idle'&&followers.length>=5;boostButton.disabled=!ready;boostButton.classList.toggle('ready',ready);boostButton.style.visibility=game==='play'?'visible':'hidden';$('mobileBoostStatus').textContent=boostState==='active'?'発動中':boostState==='betray'?'背神状態':Math.round(boost)+'%'}draw()}catch(err){console.error(err);paused=true;$('error').style.display='block';$('error').textContent='ゲーム処理エラー：'+err.message}requestAnimationFrame(frame)}requestAnimationFrame(frame);
